    def _enter(self, name):
        self.stack.append(name)
        return 1

    def _exit(self, name):
        if self.stack and self.stack[-1] == name:
            self.stack.pop()
        return 1

    def _ignore(self, name):
        self._exit(name)
        return 1

    def _count(self, count):
        self.internal_changes += count
        return 1

    def _trigger(self, sql, name):
