        when = None
        for i in range(begin):
            if tokens[i][2] != 'when' or tokens[i][3]:
                continue
            try:
                self.con.execute('EXPLAIN ' + sql[:tokens[i][0]] + ' WHEN 1 BEGIN SELECT 1; END').fetchall()
            except sqlite3.Error:
                continue
            when = i
            break
