    def _observe(self, table, columns):
        journal = self.journal
        def values(which):
            return ','.join([which + '.' + _quote(c) for c in columns] + ['NULL'] * (5 - len(columns)))
        def counted(statement):
            return statement + f'; SELECT {self.prefix}_count(changes()); '
