            ('BEFORE', 'UPDATE', initial), ('BEFORE', 'DELETE', initial),
            ('AFTER', 'UPDATE', remove + absent + latest),
            ('AFTER', 'DELETE', remove), ('AFTER', 'INSERT', absent + latest),
